"""Run user-approved anchor A/B on current service; collect faults, IO and stacks."""
import base64,fcntl,hashlib,http.client,importlib.util,io,json,os,pathlib,pwd,re,signal,stat,subprocess,tarfile,time
P=pathlib.Path;BASE=P('/home/jwk/aenv-y-clean-20261111');UNIT='jwk-aenv-y-clean-20261111.service'
BUNDLE={'anchor026_worker.py': {'base64': '', 'sha256': 'e24e4a45fa499e93907e50229ce6d65a5a75100314b3e682a3030765e5d660c4'}, 'benchmark_hook026.py': {'base64': '', 'sha256': 'e8d7455858bd7c4236a647eeed051ee4ba5bc80eaa3647fe19171178b1c3cfff'}, 'observer026.py': {'base64': '', 'sha256': '9b8344a6d23cbd7facc151a5d96b5cdc2bed930d8ab7e5a3268a2fd0175255af'}}
def sha(path):
 with path.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def main():
 assert os.getuid()==os.geteuid()==0;os.umask(0o077)
 previous=json.loads((BASE/'diagnostic025/result.json').read_text());inputs=json.loads((BASE/'runtime-prep005/result.json').read_text());pid=previous['newServerPid']
 props=dict(line.split('=',1) for line in subprocess.check_output(['systemctl','show',UNIT,'-p','MainPID','-p','ActiveState'],text=True).splitlines())
 assert props['ActiveState']=='active' and int(props['MainPID'])==pid
 assert sha(P('/proc',str(pid),'exe'))==inputs['native_inputs']['server']['sha256']
 assert sha(BASE/'config/runtime005.toml')==inputs['service_configuration']['sha256']
 assert sha(BASE/'g4-benchmark_sandbox_lifecycle.py')=='7c26ea29fe8a117859365be18bd8893b1145b3e8c7bf9cdaaeb094a2d0e13263'
 assert P('/proc/sys/kernel/random/boot_id').read_text().strip()==json.loads((BASE/'diagnostic025/runtime-identity.json').read_text())['boot_id']
 thresholds={str(i):P('/proc/sys/net/ipv4/neigh/default/gc_thresh'+str(i)).read_text().strip() for i in (1,2,3)};assert thresholds=={'1':'4096','2':'8192','3':'16384'}
 lockpath=BASE/'scripts/.run.lock';st=lockpath.lstat();assert stat.S_ISREG(st.st_mode) and st.st_uid==1002
 lockfd=os.open(lockpath,os.O_RDWR|os.O_NOFOLLOW);fcntl.flock(lockfd,fcntl.LOCK_EX|fcntl.LOCK_NB)
 for proc in P('/proc').iterdir():
  if not proc.name.isdigit():continue
  try:
   if proc.stat().st_uid==1002:
    args=(proc/'cmdline').read_bytes().split(b'\0')
    assert not any(P(a.decode(errors='replace')).name in ('benchmark_sandbox_lifecycle.py','g4-benchmark_sandbox_lifecycle.py','benchmark_hook026.py') for a in args if a),'Another benchmark is active'
  except (FileNotFoundError,PermissionError,ProcessLookupError):pass
 directory=BASE/'diagnostic026';assert not directory.exists();directory.mkdir(mode=0o700);os.chown(directory,1002,1002)
 rootcode=P('/run/jwk-aenv-y-clean-20261111/observer-code026');assert not rootcode.exists();rootcode.mkdir(mode=0o700)
 for name,row in BUNDLE.items():
  raw=base64.b64decode(row['base64'],validate=True);assert hashlib.sha256(raw).hexdigest()==row['sha256'];compile(raw,name,'exec')
  target=rootcode/name if name=='observer026.py' else directory/name;target.write_bytes(raw);target.chmod(0o700)
  if name!='observer026.py':os.chown(target,1002,1002)
 spec=importlib.util.spec_from_file_location('observer026',rootcode/'observer026.py');module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
 observer=module.Observer(directory,pid);key=(BASE/'config/api-key').read_text().strip();process=None
 env={'PATH':'/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin:/bin:/sbin','HOME':pwd.getpwnam('jwk').pw_dir,'USER':'jwk','LOGNAME':'jwk','LANG':'C.UTF-8','NO_PROXY':'localhost,127.0.0.1','no_proxy':'localhost,127.0.0.1'}
 args=['nsenter','--target',str(pid),'--net','--mount','--','setpriv','--reuid=1002','--regid=1002','--clear-groups','--inh-caps=-all','--ambient-caps=-all','--bounding-set=-all','--no-new-privs',str(BASE/'sdk/g4-e2b246/bin/python'),'-I','-B',str(directory/'anchor026_worker.py')]
 result={'serviceRestarted':False,'parameterChanges':False,'serverPid':pid,'thresholds':thresholds,'groups':['A_released','B_anchor'],'observerBarriersOutsideSdkPhaseTiming':True,'rawPerfFilesRetainedOnY':True,'success':False}
 seen=set();control=BASE/'anchor026/control';deadline=time.monotonic()+8500
 try:
  with (directory/'worker.log').open('xb') as log:
   process=subprocess.Popen(args,env=env,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
   while process.poll() is None:
    if control.exists():
     for path in sorted(control.glob('*.json')):
      if path.name in seen:continue
      assert re.fullmatch(r'(A_released|B_anchor)-\d{4}\.json',path.name) and not path.is_symlink()
      response={'ok':True}
      try:observer.event(path)
      except BaseException as error:response={'ok':False,'errorType':type(error).__name__,'error':str(error)[:1200]};result.setdefault('observerErrors',[]).append(response)
      ack=path.with_suffix('.ack');assert not ack.exists();ack.write_text(json.dumps(response)+'\n');os.chown(ack,1002,1002);seen.add(path.name)
    observer.periodic()
    if time.monotonic()>deadline:raise TimeoutError('Own anchor experiment deadline')
    time.sleep(.1)
  result['workerExitCode']=process.returncode
  result['worker']=json.loads((BASE/'anchor026/result.json').read_text())
  assert process.returncode==0 and result['worker']['success'] and result['worker']['finalInventoryCount']==0,'Anchor A/B or cleanup failed'
  assert observer.anchor_device is not None and not result.get('observerErrors'),'Anchor retention was not verified'
  result.update(success=True,anchorDevice=observer.anchor_device,anchorPid=observer.anchor_pid)
 except BaseException as error:result.update(errorType=type(error).__name__,error=str(error)[:2000]);raise
 finally:
  if process is not None and process.poll() is None:
   os.killpg(process.pid,signal.SIGTERM)
   try:process.wait(timeout=25)
   except subprocess.TimeoutExpired:os.killpg(process.pid,signal.SIGKILL);process.wait(timeout=5)
  if not result['success'] and (BASE/'anchor026/state.json').exists():
   try:
    state=json.loads((BASE/'anchor026/state.json').read_text());anchor=state.get('anchorId');token=state.get('anchorMetadata')
    if anchor:
     assert re.fullmatch(r'[0-9a-f-]{36}',anchor) and token['anchor_experiment_run'].startswith('anchor026-')
     conn=http.client.HTTPConnection('127.0.0.1',18080,timeout=15);conn.request('GET','/sandboxes/'+anchor,headers={'X-API-Key':key});response=conn.getresponse();raw=response.read();status=response.status;conn.close()
     if status!=404:
      assert status==200 and json.loads(raw)['metadata']==token
      conn=http.client.HTTPConnection('127.0.0.1',18080,timeout=20);conn.request('DELETE','/sandboxes/'+anchor,headers={'X-API-Key':key});response=conn.getresponse();response.read();assert response.status in (204,404);conn.close()
     result['rootAnchorCleanupVerified']=True
   except BaseException as error:result['rootAnchorCleanupError']=type(error).__name__+': '+str(error)[:600]
  try:observer.close()
  except BaseException as error:result['observerCloseError']=type(error).__name__+': '+str(error)[:600]
  result['profiles']=observer.profile
  # Keep exact raw perf files on Y, return decoded stacks, hashes and all other evidence.
  with (BASE/'logs/server.log').open('rb') as f:f.seek(observer.start_offset);logs=f.read(64*1024**2)
  (directory/'server-window.jsonl').write_bytes(logs);result['serverLogBytes']=len(logs)
  result['thresholdsAfter']={str(i):P('/proc/sys/net/ipv4/neigh/default/gc_thresh'+str(i)).read_text().strip() for i in (1,2,3)}
  archive=io.BytesIO()
  with tarfile.open(fileobj=archive,mode='w:gz',compresslevel=9) as tar:
   for root,prefix in [(BASE/'results/anchor026','result'),(BASE/'anchor026','control'),(directory,'observer')]:
    if not root.exists():continue
    for path in root.rglob('*'):
     if not path.is_file() or path.is_symlink() or path.suffix=='.data' or path.name=='result.json' and root==directory:continue
     if path.stat().st_size>64*1024**2:continue
     tar.add(path,arcname=prefix+'/'+str(path.relative_to(root)),recursive=False)
  blob=archive.getvalue();assert len(blob)<1200000,'Evidence archive exceeds relay limit; all files retained on Y'
  result['archive']={'sha256':hashlib.sha256(blob).hexdigest(),'bytes':len(blob),'base64':base64.b64encode(blob).decode()}
  result['workerLogTail']=(directory/'worker.log').read_text(errors='replace')[-6000:].replace(key,'[REDACTED_API_KEY]')
  (directory/'result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');os.chown(directory/'result.json',1002,1002)
  print('ANCHOR_TASK026_RESULT='+json.dumps(result,ensure_ascii=False,separators=(',',':')),flush=True)
if __name__=='__main__':main()
